tw.local.sqlStatements = new tw.object.listOf.SQLStatement();

for (var j = 0; j < tw.local.multiTenorDates.listLength; j++) {
	tw.local.sqlStatements[j] = new tw.object.SQLStatement();
	tw.local.sqlStatements[j].sql = " INSERT INTO " + tw.env.LKP_DB_Schema + ".ODC_MULTITENORDATES ( " + " REQUESRID, INSTALLMENTDATE, INSTALLMENTAMOUNT, INSTALLMENTBASEDATE, INSTALLMENTTENORDAYS, REBATEAMOUNT, LIQUIDATION_AMOUNT " + " ) VALUES" + " (?,?,?,?,?,?,?)";

	tw.local.sqlStatements[j].parameters = new tw.object.listOf.SQLParameter();

	addSQLParameter(tw.local.requestID, tw.local.sqlStatements[j].parameters);
	var instalmentMaturityDate = addOneHourToDate(tw.local.multiTenorDates[j].instalmentMaturityDate);
	addSQLParameter(instalmentMaturityDate, tw.local.sqlStatements[j].parameters);
	addSQLParameter(tw.local.multiTenorDates[j].amount, tw.local.sqlStatements[j].parameters);
	var instalmentBaseDate = addOneHourToDate(tw.local.multiTenorDates[j].instalmentBaseDate);
	addSQLParameter(instalmentBaseDate, tw.local.sqlStatements[j].parameters);
	addSQLParameter(tw.local.multiTenorDates[j].instalmentTenorDays, tw.local.sqlStatements[j].parameters);
	addSQLParameter(tw.local.multiTenorDates[j].splitRebateAmnt, tw.local.sqlStatements[j].parameters);
	addSQLParameter(tw.local.multiTenorDates[j].liquidationAmnt, tw.local.sqlStatements[j].parameters);
}
// Helper function to add SQL parameters
function addSQLParameter(value, parameters) {
	if (value == null && typeof value == "string") {
		value = "";
	} else if (value == null && typeof value == "number") {
		value = 0;
	} else if (value == null && typeof value == "boolean") {
		value = "0";
	}
	var parameter = new tw.object.SQLParameter();
	parameter.value = value;
	parameter.mode = "IN";
	parameters.insertIntoList(parameters.listLength, parameter);
}

// add function to add 1hour to the input date
function addOneHourToDate(date) {
	if (date == null) return null;
	var newDate = new Date(date);
	newDate.setHours(newDate.getHours() + 1);
	return newDate;
}
